/bin/bash -c "python - <<'PY'
import numpy as np
z=np.load('source_pixels.npz')['rgb'].astype(float)
regs={'red':(112,52,158,86),'blue':(162,48,210,86),'puck':(85,55,130,90)}
for i in range(0,96,2):
 im=z[i]; r,g,b=im.transpose(2,0,1); yy,xx=np.indices(r.shape)
 out=[]
 for name,(x0,y0,x1,y1) in regs.items():
  if name=='red': m=(r>1.35*g)&(r>1.4*b)&(r>90)&(g<150)&(b<140)
  elif name=='blue': m=(b>1.3*r)&(b>1.2*g)&(b>85)&(r<150)&(g<155)
  else: m=(r>165)&(g>165)&(b>165)&(np.abs(r-g)<20)&(np.abs(g-b)<25)
  ys,xs=np.where(m&(yy>=y0)&(yy<y1)&(xx>=x0)&(xx<x1))
  if len(xs): out.append(f'{name}:{len(xs):3d},{xs.mean():.2f},{ys.mean():.2f},{xs.min()},{xs.max()},{ys.min()},{ys.max()}')
  else: out.append(name+':0')
 print(f'{i:02d}', ' | '.join(out))
PY"

